deltas.manifest:
[package]
workspace = "../../../.."
name = "semio-framework-pack"
version = "0.1.0"
edition = "2021"
rust-version.workspace = true
description = "The .spk binary document container: header/footer/segment/manifest/chunk-table framing, the value codec, recovery, and native/async/http sources. A file format, product-neutral like the .spr record format it shares a codec with."

[package.metadata.semio]
role = "framework"
id = "pack"

[lints]
workspace = true

[lib]
name = "pack"
path = "🦀️.rs"

[[test]]
name = "pack_schema_hash"
path = "../../🌱️value/🧪️tests/🔬️schema-hash/🦀️.rs"

[features]
default = ["deflate"]
deflate = ["semio-framework-replication/deflate"]
ureq = ["dep:ureq"]
corruption-testing = []

[dependencies]
semio-framework-diagnostic = { path = "../../../⚠️diagnostic/📦️packages/🦀️rust" }
semio-framework-pack-error = { path = "../../⚠️error/📦️packages/🦀️rust" }
semio-framework-dsl-record = { path = "../../../🗣️dsl/🧬️schema/📦️packages/🦀️rust" }
semio-framework-pack-json = { path = "../../🔤️json/📦️packages/🦀️rust" }
semio-framework-replication = { workspace = true }
semio-framework-value = { path = "../../../🌱️value/📦️packages/🦀️rust" }
# 🔌️ Phase 1 (`26/08/20/INTERACTIVE-JOB-RUNTIME-REFACTOR`): `UreqRangeTransport`'s blocking HTTP
# call dispatches onto the process-wide `WorkerPool` (`Lane::Io`) instead of a per-request
# `std::thread::spawn`. Workspace-internal, not a new third-party dependency.
semio-framework-async = { workspace = true, features = ["entrypoint"] }
semio-framework-hash = { path = "../../../🔏️hash/📦️packages/🦀️rust" }
ureq = { version = "2", optional = true }

[dev-dependencies]
blake3 = "1.8.2"
semio-framework-dsl-record-derive = { path = "../../../🗣️dsl/🧬️schema/✨️derive/📦️packages/🦀️rust" }
serde = { version = "1.0.228", features = ["derive"] }
semio-framework-trace = { path = "../../../⏱️trace/📦️packages/🦀️rust" }
semio-framework-dsl = { path = "../../../🗣️dsl/📦️packages/🦀️rust" }
semio-framework-async-macros = { path = "../../../⏳️async/✨️macros/📦️packages/🦀️rust" }
serde_json = { version = "1.0.140", features = ["float_roundtrip"] }
